import{_ as a,o as t,c as o,ap as i}from"./chunks/framework.CuFS6FqL.js";const u=JSON.parse('{"title":"","description":"Privacy notice for handbook.syslifters.com.","frontmatter":{"description":"Privacy notice for handbook.syslifters.com.","search":false},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),r={name:"privacy.md"};function s(n,e,l,c,h,d){return t(),o("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /privacy.md for this page in Markdown format</div><h2 id="privacy-notice" tabindex="-1">Privacy notice <a class="header-anchor" href="#privacy-notice" aria-label="Permalink to &quot;Privacy notice&quot;">​</a></h2><h3 id="data-protection-responsibility-and-scope" tabindex="-1">Data Protection, Responsibility, and Scope <a class="header-anchor" href="#data-protection-responsibility-and-scope" aria-label="Permalink to &quot;Data Protection, Responsibility, and Scope&quot;">​</a></h3><p>We respect the privacy of our customers and other interested parties and comply with applicable laws to protect your privacy. These laws include, in particular:</p><ul><li>the European Union General Data Protection Regulation (&quot;GDPR&quot;)</li></ul><p>This privacy notice applies to:</p><ul><li>Website: handbook.syslifters.com</li></ul><p>The following categories of data subjects are covered by this data protection notice:</p><ul><li>Website visitors</li></ul><p>The party responsible for processing your personal data under this Privacy Notice is:</p><p>Syslifters GmbH<br> Eitzersthal 75<br> 2013 Göllersdorf<br> Austria<br><a href="mailto:hello@syslifters.com" target="_blank" rel="noreferrer">hello@syslifters.com</a></p><p>In the following, we explain:</p><ul><li>For what purposes personal data is collected and processed.</li><li>Which categories of personal data are affected by the collection and processing.</li><li>On what legal basis we process personal data.</li><li>Which involved third parties, acting as data processors, are engaged in the processing of personal data.</li><li>To which third parties personal data is transmitted.</li><li>Further information, such as data retention periods, the rights of data subjects, and other details that help inform you about the described data processing.</li></ul><h2 id="purposes-for-which-personal-data-is-processed" tabindex="-1">Purposes for which personal data is processed <a class="header-anchor" href="#purposes-for-which-personal-data-is-processed" aria-label="Permalink to &quot;Purposes for which personal data is processed&quot;">​</a></h2><h3 id="website-hosting" tabindex="-1">Website hosting <a class="header-anchor" href="#website-hosting" aria-label="Permalink to &quot;Website hosting&quot;">​</a></h3><p>To make our website accessible to you and ensure its secure and reliable operation, we rely on website hosting services. This involves storing website content, managing technical infrastructure, and processing certain personal data that is automatically transmitted when you visit our website. The processing of this data is necessary to maintain the functionality, security, and performance of our website, as well as to detect and prevent misuse or technical issues.</p><h4 id="categories-of-personal-data-that-are-processed" tabindex="-1">Categories of personal data that are processed: <a class="header-anchor" href="#categories-of-personal-data-that-are-processed" aria-label="Permalink to &quot;Categories of personal data that are processed:&quot;">​</a></h4><ul><li>Device Information</li><li>Log data</li><li>Technical Information</li><li>User behavior relevant for error analysis</li></ul><h4 id="legal-basis-for-processing" tabindex="-1">Legal basis for processing: <a class="header-anchor" href="#legal-basis-for-processing" aria-label="Permalink to &quot;Legal basis for processing:&quot;">​</a></h4><ul><li>Legitimate interest pursuant to Art. 6 para. 1 lit. f GDPR</li></ul><h4 id="involved-data-processors" tabindex="-1">Involved data processors: <a class="header-anchor" href="#involved-data-processors" aria-label="Permalink to &quot;Involved data processors:&quot;">​</a></h4><ul><li>GitHub, Inc., 88 Colin P Kelly Jr St, 94107 San Francisco, California, United States of America</li></ul><h4 id="additional-information" tabindex="-1">Additional information: <a class="header-anchor" href="#additional-information" aria-label="Permalink to &quot;Additional information:&quot;">​</a></h4><ul><li>Our legitimate interest lies in ensuring the security, stability, and proper functioning of our website, as well as in detecting and preventing misuse, technical faults, or unauthorized access.</li><li>Location of the datacenter where the website is hosted: United States of America</li></ul><h3 id="offering-live-chat-or-chatbot-features" tabindex="-1">Offering live chat or chatbot features <a class="header-anchor" href="#offering-live-chat-or-chatbot-features" aria-label="Permalink to &quot;Offering live chat or chatbot features&quot;">​</a></h3><p>To provide users with real-time support and assistance, we offer AI chatbot features on our platform. These features enable users to receive automated responses to their inquiries. The processing of personal data is necessary to facilitate these interactions, ensure effective communication, and improve the quality of our support services.</p><h4 id="categories-of-personal-data-that-are-processed-1" tabindex="-1">Categories of personal data that are processed: <a class="header-anchor" href="#categories-of-personal-data-that-are-processed-1" aria-label="Permalink to &quot;Categories of personal data that are processed:&quot;">​</a></h4><ul><li>Communications Data</li><li>Cookies and similar technologies</li><li>Information you provide as free text</li><li>Technical Information</li></ul><h4 id="legal-basis-for-processing-1" tabindex="-1">Legal basis for processing: <a class="header-anchor" href="#legal-basis-for-processing-1" aria-label="Permalink to &quot;Legal basis for processing:&quot;">​</a></h4><ul><li>Legitimate interest pursuant to Art. 6 para. 1 lit. f GDPR</li></ul><h4 id="involved-data-processors-1" tabindex="-1">Involved data processors: <a class="header-anchor" href="#involved-data-processors-1" aria-label="Permalink to &quot;Involved data processors:&quot;">​</a></h4><ul><li>Nebius Group N.V.. Schiphol Boulevard 165 1118 BG SCHIPHOL, Netherlands</li></ul><h4 id="additional-information-1" tabindex="-1">Additional information: <a class="header-anchor" href="#additional-information-1" aria-label="Permalink to &quot;Additional information:&quot;">​</a></h4><ul><li>Our legitimate interest lies in providing timely and effective support to users, resolving their inquiries, and enhancing the overall quality of our services.</li><li>We ask that you do not transmit any special categories of personal data when contacting us. These categories include the following data: <ul><li>Ethnic origin.</li><li>Political opinions.</li><li>Religious or philosophical beliefs.</li><li>Trade union membership.</li><li>Genetic data.</li><li>Biometric data.</li><li>Health data.</li><li>Data concerning sex life or sexual orientation.</li></ul></li><li>If we become aware of a transfer of sensitive categories of data, we will arrange for these to be deleted under consideration of reasonable effort.</li></ul><h2 id="additional-information-2" tabindex="-1">Additional Information <a class="header-anchor" href="#additional-information-2" aria-label="Permalink to &quot;Additional Information&quot;">​</a></h2><h3 id="data-retention" tabindex="-1">Data retention <a class="header-anchor" href="#data-retention" aria-label="Permalink to &quot;Data retention&quot;">​</a></h3><p>We retain your personal data only for as long as necessary to fulfill the purposes described in this privacy notice, or as long as required by contractual or legal retention obligations. Once your personal data is no longer needed for these purposes, or when applicable retention periods have expired, your data will be deleted or anonymized in accordance with applicable data protection laws</p><h3 id="protection-of-personal-data" tabindex="-1">Protection of Personal Data <a class="header-anchor" href="#protection-of-personal-data" aria-label="Permalink to &quot;Protection of Personal Data&quot;">​</a></h3><p>We safeguard personal data by implementing appropriate technical and organizational measures in accordance with applicable data protection laws and recognized industry standards. These measures include, where feasible, the pseudonymization and encryption of personal data both in transit and at rest. Our security practices are regularly reviewed and updated to ensure the ongoing confidentiality, integrity, and availability of your personal information.</p><h3 id="withdrawal-of-consent" tabindex="-1">Withdrawal of consent <a class="header-anchor" href="#withdrawal-of-consent" aria-label="Permalink to &quot;Withdrawal of consent&quot;">​</a></h3><p>If you have given your consent to the processing of your personal data for a specific purpose based on Art. 6 para. 1 lit. a GDPR, you can withdraw this consent at any time. The lawfulness of the processing of the personal data until the withdrawal is not affected by the withdrawal.</p><h3 id="transfer-of-data" tabindex="-1">Transfer of data <a class="header-anchor" href="#transfer-of-data" aria-label="Permalink to &quot;Transfer of data&quot;">​</a></h3><p>We only transfer or disclose your personal data to third parties when required by applicable law, regulation, or legal process, or when it is necessary for the performance or provision of our services to you. In all cases, we ensure that any transfer of your personal data complies with relevant data protection laws, including the General Data Protection Regulation (GDPR) where applicable. Third-party data processors process personal data only as necessary to deliver the agreed-upon services, in accordance with our instructions and applicable data protection agreements. We do not sell your personal data to third parties. If we intend to use your personal data for purposes that require your consent under applicable law, we will obtain your explicit consent beforehand.</p><h3 id="rights-of-data-subjects" tabindex="-1">Rights of Data Subjects <a class="header-anchor" href="#rights-of-data-subjects" aria-label="Permalink to &quot;Rights of Data Subjects&quot;">​</a></h3><h4 id="right-of-access" tabindex="-1">Right of Access <a class="header-anchor" href="#right-of-access" aria-label="Permalink to &quot;Right of Access&quot;">​</a></h4><p>You have the right to request at any time information about the personal data we store about you and to receive a copy of that information. Furthermore, you have the right to obtain confirmation as to whether the personal data in question is being processed.</p><h4 id="right-to-rectification" tabindex="-1">Right to Rectification <a class="header-anchor" href="#right-to-rectification" aria-label="Permalink to &quot;Right to Rectification&quot;">​</a></h4><p>Should your data be inaccurate or incomplete, we will rectify it upon request.</p><h4 id="right-to-data-portability" tabindex="-1">Right to Data Portability <a class="header-anchor" href="#right-to-data-portability" aria-label="Permalink to &quot;Right to Data Portability&quot;">​</a></h4><p>If we process your personal data in an automated way based on your consent or based on a corresponding agreement, you have the right to request a copy of your data in a structured, commonly used, and machine-readable format, which can be sent to you or another party. This right applies only to the personal data that you have provided to us.</p><h4 id="right-to-restriction-of-processing" tabindex="-1">Right to Restriction of Processing <a class="header-anchor" href="#right-to-restriction-of-processing" aria-label="Permalink to &quot;Right to Restriction of Processing&quot;">​</a></h4><p>You have the right to request that we restrict the processing of your personal data under certain circumstances.</p><h4 id="right-to-erasure" tabindex="-1">Right to Erasure <a class="header-anchor" href="#right-to-erasure" aria-label="Permalink to &quot;Right to Erasure&quot;">​</a></h4><p>You have the right to have the personal data processed by us deleted, insofar as this is legally permissible.</p><h4 id="objection-to-processing" tabindex="-1">Objection to Processing <a class="header-anchor" href="#objection-to-processing" aria-label="Permalink to &quot;Objection to Processing&quot;">​</a></h4><p>You can object to the processing of your personal data, for example, by not using certain services. If you object to the processing of your personal data for certain purposes, this may result in the inability to use the services concerned.</p><h4 id="right-to-lodge-a-complaint" tabindex="-1">Right to Lodge a Complaint <a class="header-anchor" href="#right-to-lodge-a-complaint" aria-label="Permalink to &quot;Right to Lodge a Complaint&quot;">​</a></h4><p>If you believe that we are not processing your personal data correctly, you can contact us. You also have the right to lodge a complaint with a supervisory authority. For more information on the supervisory authorities in the European Union, please click <a href="https://ec.europa.eu/justice/article-29/structure/data-protection-authorities/index_en.htm" target="_blank" rel="noreferrer">here</a>.</p><p>All rights can be exercised by sending an e-mail to the contact named at the beginning of this privacy notice.</p><h2 id="changes-to-this-privacy-notice" tabindex="-1">Changes to this privacy notice <a class="header-anchor" href="#changes-to-this-privacy-notice" aria-label="Permalink to &quot;Changes to this privacy notice&quot;">​</a></h2><p>We may update this privacy notice occasionally to reflect changes in our data processing practices, legal requirements, or other operational needs. Any modifications will be published on this page, and the &quot;Date of publication&quot; below will be updated accordingly. We encourage you to review this notice periodically to stay informed about how we protect your personal data.</p><p>Date of publication of the current version: 11.06.2026</p>',62)])])}const f=a(r,[["render",s]]);export{u as __pageData,f as default};
